class Solution {
  public int[] bestTower(int[][] towers, int[] center, int radius) {
    int bx = -1, by = -1, bq = -1;
    for (int[] t : towers) {
      if (Math.abs(t[0] - center[0]) + Math.abs(t[1] - center[1]) > radius) continue;
      if (t[2] > bq || (t[2] == bq && (t[0] < bx || (t[0] == bx && t[1] < by)))) {
        bx = t[0];
        by = t[1];
        bq = t[2];
      }
    }
    return new int[] {bx, by};
  }
}
